"use client";
import Link from "next/link";import {useEffect,useMemo,useState} from "react";import {ArrowLeft,CheckCircle2,Loader2,PackagePlus} from "lucide-react";import {createClient} from "@/lib/supabase/client";
const featureFor:Record<string,string>={product:"FTR-MARKETPLACE-PRODUCTS",service:"FTR-MARKETPLACE-SERVICES",course:"FTR-MARKETPLACE-COURSES",job:"FTR-MARKETPLACE-JOBS"};type StoreRow={id:string;name:string};type Listing={id:string;owner_user_id:string;store_id:string|null;category_id:string|null;item_type:string;title:string;slug:string;description:string|null;price:number|null;currency_code:string|null;is_free:boolean};
export default function NewListingPage(){const supabase=createClient();const[editId,setEditId]=useState<string|null>(null);const[type,setType]=useState("product");const[title,setTitle]=useState("");const[description,setDescription]=useState("");const[price,setPrice]=useState("");const[currency,setCurrency]=useState("USD");const[storeId,setStoreId]=useState("");const[categoryId,setCategoryId]=useState("");const[stores,setStores]=useState<StoreRow[]>([]);const[categories,setCategories]=useState<{id:string;name:string}[]>([]);const[loading,setLoading]=useState(true);const[saving,setSaving]=useState(false);const[error,setError]=useState("");const[success,setSuccess]=useState("");const isFree=useMemo(()=>price.trim()==="",[price]);useEffect(()=>{(async()=>{const searchEdit=typeof window!=="undefined"?new URLSearchParams(window.location.search).get("edit"):null;setEditId(searchEdit);const{data:{user}}=await supabase.auth.getUser();if(!user){window.location.href=`/login?next=${encodeURIComponent(searchEdit?`/vendor/listings/new?edit=${searchEdit}`:"/vendor/listings/new")}`;return}const[storeResult,categoryResult]=await Promise.all([supabase.from("stores").select("id,name").eq("owner_user_id",user.id).order("name"),supabase.from("listing_categories").select("id,name").eq("status","active").order("name")]);setStores((storeResult.data||[]) as StoreRow[]);setCategories((categoryResult.data||[]) as {id:string;name:string}[]);if(searchEdit){const{data,error:e}=await supabase.from("marketplace_items").select("id,owner_user_id,store_id,category_id,item_type,title,slug,description,price,currency_code,is_free").eq("id",searchEdit).eq("owner_user_id",user.id).maybeSingle();if(e||!data){setError(e?.message||"Listing not found or you do not own it.");setLoading(false);return}const item=data as Listing;setType(item.item_type);setTitle(item.title);setDescription(item.description||"");setPrice(item.is_free?"":item.price==null?"":String(item.price));setCurrency((item.currency_code||"USD").trim());setStoreId(item.store_id||"");setCategoryId(item.category_id||"")}setLoading(false)})()},[supabase]);async function save(){setSaving(true);setError("");setSuccess("");const{data:{user}}=await supabase.auth.getUser();if(!user){setError("Please sign in again.");setSaving(false);return}if(title.trim().length<3){setError("Title must be at least 3 characters.");setSaving(false);return}const featureId=featureFor[type];if(!featureId){setError("Unsupported listing type.");setSaving(false);return}const slugBase=title.trim().toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");const slug=editId?`${slugBase}-${editId.slice(0,8)}`:`${slugBase}-${crypto.randomUUID().slice(0,8)}`;const payload={owner_user_id:user.id,store_id:storeId||null,category_id:categoryId||null,item_type:type,title:title.trim(),slug,description:description.trim()||null,price:isFree?null:Number(price),currency_code:isFree?null:currency,is_free:isFree,status:"draft"};if(editId){const{error:e}=await supabase.from("marketplace_items").update(payload).eq("id",editId).eq("owner_user_id",user.id);if(e){setError(e.message);setSaving(false);return}const{data:submission}=await supabase.from("listing_submissions").select("id").eq("entity_id",editId).eq("owner_user_id",user.id).order("created_at",{ascending:false}).limit(1).maybeSingle();if(submission)await supabase.from("listing_submissions").update({submission_status:"submitted",submitted_at:new Date().toISOString(),reviewed_by:null,reviewed_at:null,review_message:null,updated_at:new Date().toISOString()}).eq("id",submission.id);setSuccess("Listing updated and returned to review.");setSaving(false);return}const{data:item,error:itemError}=await supabase.from("marketplace_items").insert(payload).select("id,public_id").single();if(itemError||!item){setError(itemError?.message||"Could not create listing.");setSaving(false);return}const{error:submissionError}=await supabase.rpc("create_listing_submission",{feature_id_input:featureId,entity_id_input:item.id,is_free_input:isFree,metadata_input:{source:"vendor_center",item_type:type}});if(submissionError){setError(`Listing draft was created, but submission failed: ${submissionError.message}`);setSaving(false);return}setSuccess(`Submitted successfully. Listing ID: ${item.public_id||item.id}`);setTitle("");setDescription("");setPrice("");setStoreId("");setCategoryId("");setSaving(false)}if(loading)return <main className="mx-auto max-w-3xl px-4 py-10"><div className="h-96 animate-pulse rounded-2xl border border-[var(--border)] bg-[var(--surface)]"/></main>;return <main className="mx-auto max-w-3xl px-4 py-7 sm:px-6 lg:px-8"><Link href="/vendor/listings" className="inline-flex items-center gap-2 text-sm text-[var(--muted)]"><ArrowLeft size={16}/>My listings</Link><section className="mt-6 rounded-[2rem] border border-[var(--border)] bg-[var(--surface)] p-6 sm:p-8"><div className="flex items-start gap-4"><div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-[var(--primary)] text-[var(--background)]"><PackagePlus size={22}/></div><div><p className="text-xs font-semibold uppercase tracking-widest text-[var(--muted)]">Vendor Center</p><h1 className="mt-1 text-3xl font-semibold">{editId?"Edit listing":"Add a listing"}</h1><p className="mt-2 text-sm leading-6 text-[var(--muted)]">Create the listing first; DRIGHT&apos;s existing submission and approval workflow controls publication.</p></div></div><div className="mt-7 grid gap-5 sm:grid-cols-2"><label className="text-sm font-medium">Type<select value={type} onChange={e=>setType(e.target.value)} disabled={Boolean(editId)} className="mt-2 w-full rounded-xl border border-[var(--border)] bg-[var(--background)] px-3 py-3 text-sm"><option value="product">Product</option><option value="service">Service</option><option value="course">Course</option><option value="job">Job</option></select></label><label className="text-sm font-medium">Store (optional)<select value={storeId} onChange={e=>setStoreId(e.target.value)} className="mt-2 w-full rounded-xl border border-[var(--border)] bg-[var(--background)] px-3 py-3 text-sm"><option value="">No store selected</option>{stores.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label></div><label className="mt-5 block text-sm font-medium">Category (optional)<select value={categoryId} onChange={e=>setCategoryId(e.target.value)} className="mt-2 w-full rounded-xl border border-[var(--border)] bg-[var(--background)] px-3 py-3 text-sm"><option value="">No category</option>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label className="mt-5 block text-sm font-medium">Title<input value={title} onChange={e=>setTitle(e.target.value)} maxLength={160} placeholder="What are you offering?" className="mt-2 w-full rounded-xl border border-[var(--border)] bg-[var(--background)] px-3 py-3 text-sm outline-none"/></label><label className="mt-5 block text-sm font-medium">Description<textarea value={description} onChange={e=>setDescription(e.target.value)} rows={7} placeholder="Explain what the buyer receives, who it is for and what makes it valuable." className="mt-2 w-full rounded-xl border border-[var(--border)] bg-[var(--background)] px-3 py-3 text-sm outline-none"/></label><div className="mt-5 grid gap-5 sm:grid-cols-2"><label className="text-sm font-medium">Price <span className="font-normal text-[var(--muted)]">(leave blank for free/contact)</span><input value={price} onChange={e=>setPrice(e.target.value.replace(/[^0-9.]/g,""))} inputMode="decimal" placeholder="0.00" className="mt-2 w-full rounded-xl border border-[var(--border)] bg-[var(--background)] px-3 py-3 text-sm"/></label><label className="text-sm font-medium">Currency<select value={currency} onChange={e=>setCurrency(e.target.value)} disabled={isFree} className="mt-2 w-full rounded-xl border border-[var(--border)] bg-[var(--background)] px-3 py-3 text-sm"><option>USD</option><option>NGN</option><option>GBP</option><option>EUR</option><option>CAD</option><option>AUD</option></select></label></div>{error&&<div className="mt-5 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">{error}</div>}{success&&<div className="mt-5 flex items-start gap-3 rounded-xl border border-emerald-200 bg-emerald-50 p-4 text-sm text-emerald-700"><CheckCircle2 size={18}/>{success}</div>}<div className="mt-6 flex flex-col-reverse gap-3 sm:flex-row sm:justify-end"><Link href="/vendor/listings" className="inline-flex items-center justify-center rounded-xl border border-[var(--border)] px-5 py-3 text-sm font-semibold">Cancel</Link><button onClick={save} disabled={saving} className="inline-flex items-center justify-center gap-2 rounded-xl bg-[var(--primary)] px-5 py-3 text-sm font-semibold text-[var(--background)] disabled:opacity-60">{saving&&<Loader2 size={16} className="animate-spin"/>}{saving?"Saving…":editId?"Save & resubmit":"Create & submit for review"}</button></div></section></main>}
